import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

let nextId = 4;
const fakeCreate = (product) => new Promise((res) => setTimeout(() => res({ id: "p" + nextId++, ...product }), 200));

function App() {
  const [items, setItems] = useState([
    { id: "p1", name: "Чихэвч" }, { id: "p2", name: "Гар цаг" }, { id: "p3", name: "Ном" },
  ]);

  function add() {
    fakeCreate({ name: "Гутал" }).then((created) => {
      setItems((prev) => [...prev, created]);
    });
  }

  return (
    <View style={styles.s}>
      {items.map((it) => <Text key={it.id} testID="row" style={styles.row}>{it.name}</Text>)}
      <Pressable nativeID="add" style={styles.btn} onPress={add}>
        <Text style={styles.btnText}>+ Шинэ бараа</Text>
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 16, gap: 8 },
  row: { fontSize: 16, paddingVertical: 10, borderBottomWidth: 1, borderColor: "#e2e8f0" },
  btn: { backgroundColor: "#16a34a", padding: 14, borderRadius: 10, alignItems: "center", marginTop: 12 },
  btnText: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);
